-- DeepSeek — Чат-боти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'deepseek.com' OR LOWER(`name`) = LOWER('DeepSeek'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'DeepSeek', NULL, 'https://www.deepseek.com', NULL, NULL, 'Китайська AI-лабораторія та чат-бот на моделях DeepSeek V4 і R1: веб-чат, мобільний застосунок, настільна програма та API для розробників.', 'A Chinese AI lab and chatbot built on the DeepSeek V4 and R1 models: web chat, a mobile app, a desktop app and a developer API.', 'DeepSeek розробляє великі мовні моделі — від серії V (зокрема V4 і V4.1-Flash з покращеною роботою агентів і розумінням зображень) до моделі міркувань R1. Чат доступний у вебі на chat.deepseek.com, у мобільному застосунку та настільній програмі, а розробники можуть підключити моделі через API з оплатою за токени. Ваги частини моделей опубліковано для завантаження. Перед використанням варто ознайомитися з політикою конфіденційності сервісу.', 'DeepSeek develops large language models — from the V series (including V4 and V4.1-Flash with improved agent performance and image understanding) to the R1 reasoning model. Chat is available on the web at chat.deepseek.com, in a mobile app and a desktop app, and developers can use the models via an API billed per token. Weights for some models are available for download. Review the service''s privacy policy before use.', 'Моделі серії V4 і модель міркувань R1
Веб, мобільний і настільний застосунки
API з оплатою за токени
Відкриті ваги частини моделей', 'V4-series models and the R1 reasoning model
Web, mobile and desktop apps
Pay-per-token API
Open weights for some models', 'Користувачі чат-ботів і розробники, які шукають потужні та доступні моделі.', 'Chatbot users and developers looking for capable, affordable models.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
