SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'chat.mistral.ai' OR LOWER(`name`) = LOWER('Le Chat (Mistral AI)'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Le Chat (Mistral AI)', NULL, 'https://chat.mistral.ai', NULL, NULL, 'Чат-бот і агентна платформа французької компанії Mistral AI: розмови, пошук, програмування та автоматизація задач з європейським підходом до даних.', 'The chatbot and agent platform from French company Mistral AI: conversation, search, coding and task automation with a European approach to data.', 'Le Chat — асистент від Mistral AI, європейської компанії з Франції, яка робить ставку на суверенні та відкриті альтернативи американським AI-провайдерам. Він відповідає на запитання, шукає в інтернеті, допомагає з кодом у вебі, терміналі та IDE й автоматизує задачі; для компаній є понад 100 конекторів до корпоративних даних. Тарифи: Free — обмежений доступ і $10 API-кредитів на місяць; Pro — $14,99 на місяць ($5,99 для студентів, $30 API-кредитів); Team — $24,99 за користувача на місяць (мінімум $50); Enterprise — за запитом, з власними моделями й SAML SSO.', 'Le Chat is the assistant from Mistral AI, a European company based in France that focuses on sovereign, open alternatives to US AI providers. It answers questions, searches the web, helps with code on the web, in the terminal and in IDEs, and automates tasks; companies get 100+ connectors to enterprise data. Plans: Free — limited access and $10 of API credits a month; Pro — $14.99 a month ($5.99 for students, $30 of API credits); Team — $24.99 per user a month (minimum $50); Enterprise on request, with custom models and SAML SSO.', 'Чат, пошук і програмування
Європейська компанія (Франція)
100+ конекторів до даних компанії
API-кредити в кожному тарифі', 'Chat, search and coding
European company (France)
100+ connectors to company data
API credits on every plan', 'Користувачі й компанії в Європі, яким важливі суверенітет даних і відкриті моделі.', 'Users and companies in Europe who value data sovereignty and open models.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
