-- Grok — Чат-боти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'grok.com' OR LOWER(`name`) = LOWER('Grok'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Grok', NULL, 'https://grok.com', NULL, NULL, 'AI-асистент від xAI: чат, пошук актуальної інформації в інтернеті та X, міркування крок за кроком, генерація зображень, відео й коду та мультиагентний режим.', 'xAI''s AI assistant: chat, live search across the web and X, step-by-step reasoning, image, video and code generation and a multi-agent mode.', 'Grok — AI-асистент компанії xAI, доступний у вебі, на iOS та Android. Він шукає в інтернеті та в X у реальному часі й посилається на першоджерела, показує хід міркувань, генерує зображення, відео й код у тому самому діалозі та підтримує природні голосові розмови. У мультиагентному режимі кілька агентів паралельно розв''язують частини складного завдання й об''єднують результат в одну відповідь із посиланнями. Користуватися можна безкоштовно; підписка SuperGrok відкриває розширені можливості (ціна — у застосунку).', 'Grok is xAI''s AI assistant, available on the web, iOS and Android. It searches the web and X in real time and cites primary sources, shows its reasoning, generates images, video and code in the same thread and supports natural voice conversations. In multi-agent mode several agents work on parts of a hard problem in parallel and merge the result into one cited answer. You can use it for free; a SuperGrok subscription unlocks advanced features (priced in the app).', 'Пошук в інтернеті та X у реальному часі
Генерація зображень, відео й коду
Голосові розмови
Мультиагентний режим', 'Live search across the web and X
Image, video and code generation
Voice conversations
Multi-agent mode', 'Усі, кому потрібні свіжі новини та відповіді з посиланнями.', 'Anyone who wants up-to-date news and cited answers.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
