-- Poe — Чат-боти
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'poe.com' OR LOWER(`name`) = LOWER('Poe'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Poe', NULL, 'https://poe.com', NULL, NULL, 'Платформа від Quora, де в одному місці можна спілкуватися з тисячами AI-моделей і ботів — GPT, Claude, Gemini, Grok та інших, приватно чи в груповому чаті.', 'A platform from Quora where you can chat with thousands of AI models and bots in one place — GPT, Claude, Gemini, Grok and more, privately or in group chats.', 'Poe від Quora збирає провідні AI-моделі та тисячі ботів в одному застосунку. Можна перемикатися між моделями OpenAI, Anthropic, Google, xAI та інших розробників, порівнювати відповіді, генерувати зображення й відео, створювати власних ботів і спілкуватися з AI у групових чатах. Доступно у вебі, на мобільних і настільних пристроях. Ціни підписки на сайті не опубліковано — їх показано після входу.', 'Poe from Quora brings leading AI models and thousands of bots together in one app. You can switch between models from OpenAI, Anthropic, Google, xAI and other developers, compare answers, generate images and video, create your own bots and chat with AI in group chats. It is available on the web, mobile and desktop. Subscription prices are not published on the website — they are shown after sign-in.', 'Тисячі моделей і ботів в одному місці
