INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Claude Code', NULL, 'https://claude.com/product/claude-code', NULL, NULL, 'AI-агент для програмування від Anthropic: працює в терміналі, IDE та браузері, планує зміни, пише код, запускає тести й відкриває pull request.', 'Anthropic''s agentic coding tool: it works in the terminal, IDE and browser, plans changes, writes code, runs tests and opens pull requests.', 'Claude Code — агент для програмування від Anthropic. Він вивчає кодову базу за допомогою агентного пошуку, планує зміни, пише код, запускає тести та відкриває pull request — від виправлення бага до багатоденної міграції. Працює в терміналі, як розширення для VS Code і JetBrains, у настільному застосунку для macOS, Linux і Windows, у браузері й мобільних застосунках, а також через Slack і GitHub Actions. Claude Code входить у підписки Claude Pro ($20 на місяць або $17 при річній оплаті) і Max ($100 чи $200 на місяць); також можна платити за використання API.', 'Claude Code is Anthropic''s coding agent. It explores the codebase with agentic search, plans changes, writes code, runs tests and opens pull requests — from a bug fix to a multi-day migration. It works in the terminal, as an extension for VS Code and JetBrains, in a desktop app for macOS, Linux and Windows, in the browser and mobile apps, and via Slack and GitHub Actions. Claude Code is included with Claude Pro ($20 a month or $17 billed annually) and Max ($100 or $200 a month); you can also pay for API usage.', 'Агентне виконання задач у репозиторії
