INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Replicate', NULL, 'https://replicate.com', NULL, NULL, 'Запуск тисяч AI-моделей через API без власної інфраструктури: генерація зображень, відео, мовні моделі та розгортання власних моделей з оплатою за секунду.', 'Run thousands of AI models via API without your own infrastructure: image and video generation, language models and custom model deployment billed per second.', 'Replicate хостить тисячі відкритих і власних AI-моделей, які можна викликати через API без налаштування серверів. Більшість моделей тарифікується за часом роботи обладнання — платите лише за секунди обробки (наприклад, GPU Nvidia T4 — $0,000225 за секунду, H100 — $0,001525), а частина — за результат: FLUX Pro — $0,04 за зображення, FLUX Dev — $0,025. Можна розгортати й донавчати власні моделі на виділеному обладнанні.', 'Replicate hosts thousands of open-source and proprietary AI models that you can call via API without setting up servers. Most models are billed by hardware time — you pay only for the seconds of processing (for example, an Nvidia T4 GPU costs $0.000225 per second, an H100 $0.001525) — and some are billed per output: FLUX Pro costs $0.04 per image, FLUX Dev $0.025. You can also deploy and fine-tune your own models on dedicated hardware.', 'Тисячі моделей через API
Оплата за секунду обробки
Донавчання й власні моделі
Генерація зображень, відео й тексту', 'Thousands of models via API
Pay per second of processing
Fine-tuning and custom models
Image, video and text generation', 'Розробники, які додають AI в продукти без власних GPU.', 'Developers adding AI to products without their own GPUs.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
