-- LangChain — API
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'langchain.com' OR LOWER(`name`) = LOWER('LangChain'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'LangChain', NULL, 'https://www.langchain.com', NULL, NULL, 'Відкритий фреймворк для створення AI-агентів і платформа LangSmith для їх відстеження, оцінювання, розгортання та керування.', 'An open-source framework for building AI agents and the LangSmith platform for tracing, evaluating, deploying and managing them.', 'LangChain — один із найпоширеніших відкритих фреймворків для створення застосунків і агентів на мовних моделях. Платформа LangSmith доповнює його інструментами для всього життєвого циклу агентів: трасування й спостереження, оцінювання якості, розгортання та керування. Тарифи LangSmith: Developer — безкоштовно для одного розробника (5 000 трасувань на місяць); Plus — $39 за місце на місяць (10 000 трасувань, невелике безсерверне розгортання); Enterprise — за запитом, з розгортанням у власній інфраструктурі. Понад ліміт — $1 за умовну одиницю використання.', 'LangChain is one of the most widely used open-source frameworks for building applications and agents on language models. The LangSmith platform adds tools for the whole agent lifecycle: tracing and observability, quality evaluation, deployment and management. LangSmith plans: Developer — free for one developer (5,000 traces a month); Plus — $39 per seat a month (10,000 traces, a small serverless deployment); Enterprise on request, with self-hosted deployment. Usage beyond limits costs $1 per standard usage unit.', 'Відкритий фреймворк для агентів
Трасування й оцінювання в LangSmith
Розгортання агентів
Self-hosted для Enterprise', 'Open-source agent framework
